import{actionRequestName}from"#shared/action-request-name.js";import{displayTitle}from"#shared/display-name.js";import{SKILL_TOOL_NAME}from"#protocol/catalog-tools.js";function toMessageInputRequest(e){return{allowFreeform:e.allowFreeform,display:e.display,kind:e.kind,options:e.options,prompt:e.prompt,requestId:e.requestId}}function createToolMetadata(e,t){return{eve:{inputRequest:t?.inputRequest,kind:e.kind,label:t?.label,name:e.name}}}function mergeToolMetadata(e,t){let n=t.eve?.kind??e?.eve?.kind??`unknown`,r=t.eve?.name??e?.eve?.name??`unknown`;return{eve:{...e?.eve,...t.eve,inputRequest:t.eve?.inputRequest??e?.eve?.inputRequest,inputResponse:t.eve?.inputResponse??e?.eve?.inputResponse,kind:n,label:t.eve?.label??e?.eve?.label,name:r}}}function normalizeActionRequest(e){let t=actionRequestName(e);switch(e.kind){case`load-skill`:return{kind:`load-skill`,name:t,toolName:SKILL_TOOL_NAME};case`tool-call`:case`workflow-tool-call`:return{kind:`tool-call`,name:t,toolName:t};case`subagent-call`:case`remote-agent-call`:return{kind:`subagent-call`,name:t,toolName:`eve:subagent:${t}`}}}function normalizeActionResult(e){switch(e.kind){case`load-skill-result`:return{kind:`load-skill`,name:e.name,toolName:SKILL_TOOL_NAME};case`tool-result`:return{kind:`tool-call`,name:e.toolName,toolName:e.toolName};case`subagent-result`:return{kind:`subagent-call`,name:e.subagentName,toolName:`eve:subagent:${e.subagentName}`}}}function settledLabel(e,t,n){return t??e?.eve?.label??displayTitle(n.name)}function stringifyUnknown(e){if(typeof e==`string`)return e;try{return JSON.stringify(e)}catch{return`Action failed.`}}export{createToolMetadata,mergeToolMetadata,normalizeActionRequest,normalizeActionResult,settledLabel,stringifyUnknown,toMessageInputRequest};